from functools import wraps
from flask import request
from errors import raise_error, ERR_AUTH_REQUIRED, ERR_FORBIDDEN

VALID_ROLES = {"Customer", "Restaurant", "Rider", "CustomerService", "PlatformAdmin"}


def get_auth():
    user_id = request.headers.get("X-User-ID")
    user_role = request.headers.get("X-User-Role")
    if not user_id or not user_role or user_role not in VALID_ROLES:
        raise_error(ERR_AUTH_REQUIRED, "Missing or invalid authentication headers.")
    return user_id, user_role


def require_roles(*allowed_roles):
    def decorator(f):
        @wraps(f)
        def wrapper(*args, **kwargs):
            user_id, user_role = get_auth()
            if user_role not in allowed_roles:
                raise_error(ERR_FORBIDDEN, f"Role '{user_role}' is not authorized for this endpoint.")
            request.user_id = user_id
            request.user_role = user_role
            return f(*args, **kwargs)
        return wrapper
    return decorator

import uuid
from clock import logical_clock


def new_id():
    return str(uuid.uuid4())


def now_ts():
    return logical_clock.now()


def format_ts(dt):
    return logical_clock.format_timestamp(dt)


class VersionedModel:
    def __init__(self):
        self.id = new_id()
        ts = now_ts()
        self.created_at = ts
        self.updated_at = ts
        self.version = 1

    def touch(self):
        self.updated_at = now_ts()
        self.version += 1

    def check_version(self, client_version):
        from errors import raise_error, ERR_VERSION_CONFLICT
        if client_version is not None and client_version != self.version:
            raise_error(ERR_VERSION_CONFLICT, "Version conflict.")

    def base_dict(self):
        return {
            "id": self.id,
            "created_at": format_ts(self.created_at),
            "updated_at": format_ts(self.updated_at),
            "version": self.version,
        }


class SimpleModel:
    def __init__(self):
        self.id = new_id()
        self.created_at = now_ts()

    def base_dict(self):
        return {
            "id": self.id,
            "created_at": format_ts(self.created_at),
        }

from decimal import Decimal, ROUND_HALF_UP


def compute_tiered_commission(subtotal_cents):
    subtotal = Decimal(subtotal_cents)
    tier1_cap = Decimal(20000)
    tier2_cap = Decimal(50000)
    tier1_rate = Decimal("0.15")
    tier2_rate = Decimal("0.18")
    tier3_rate = Decimal("0.22")

    tier1_amount = min(subtotal, tier1_cap)
    tier2_amount = max(Decimal(0), min(subtotal, tier2_cap) - tier1_cap)
    tier3_amount = max(Decimal(0), subtotal - tier2_cap)

    total = tier1_amount * tier1_rate + tier2_amount * tier2_rate + tier3_amount * tier3_rate
    return int(total.quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def compute_flat_commission(subtotal_cents, rate):
    subtotal = Decimal(subtotal_cents)
    rate_d = Decimal(str(rate))
    total = subtotal * rate_d
    return int(total.quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def compute_commission(subtotal_cents, commission_rate_override=None):
    if commission_rate_override is not None:
        return compute_flat_commission(subtotal_cents, commission_rate_override)
    return compute_tiered_commission(subtotal_cents)

from decimal import Decimal, ROUND_HALF_UP
from storage import db


def recompute_acceptance_rate(rider):
    offers = []
    for a in db.assignments.values():
        if a.rider_id == rider.id and a.status in ("ACCEPTED", "PICKED_UP", "DELIVERED", "REJECTED", "CANCELLED"):
            offers.append(a)
    offers.sort(key=lambda a: a.created_at, reverse=True)
    last_30 = offers[:30]
    if not last_30:
        rider.acceptance_rate = 1.0
        return
    accepted = sum(1 for a in last_30 if a.status in ("ACCEPTED", "PICKED_UP", "DELIVERED", "CANCELLED"))
    rider.acceptance_rate = round(accepted / len(last_30), 10)


def recompute_on_time_rate(rider):
    delivered = []
    for a in db.assignments.values():
        if a.rider_id == rider.id and a.status == "DELIVERED":
            delivered.append(a)
    delivered.sort(key=lambda a: a.delivered_at, reverse=True)
    last_30 = delivered[:30]
    if len(last_30) < 10:
        rider.on_time_rate = 1.0
        return
    on_time = 0
    for a in last_30:
        order = db.orders.get(a.order_id)
        if order and a.delivered_at <= order.promised_delivery_time:
            on_time += 1
    rider.on_time_rate = round(on_time / len(last_30), 10)


def recompute_bonus_tier(rider):
    score = Decimal("0.6") * Decimal(str(rider.on_time_rate)) + \
            Decimal("0.3") * Decimal(str(rider.acceptance_rate)) + \
            Decimal("0.1") * (Decimal(str(rider.rating)) / Decimal("5"))
    score = score.quantize(Decimal("0.001"), rounding=ROUND_HALF_UP)
    score_f = float(score)
    if score_f >= 0.90:
        rider.bonus_tier = "PLATINUM"
    elif score_f >= 0.80:
        rider.bonus_tier = "GOLD"
    elif score_f >= 0.70:
        rider.bonus_tier = "SILVER"
    else:
        rider.bonus_tier = "BRONZE"


def recompute_rating(rider):
    delivered = []
    for a in db.assignments.values():
        if a.rider_id == rider.id and a.status == "DELIVERED":
            delivered.append(a)
    delivered.sort(key=lambda a: a.delivered_at, reverse=True)
    last_30 = delivered[:30]
    if not last_30:
        rider.rating = 5.0
        return
    ratings = []
    for a in last_30:
        order = db.orders.get(a.order_id)
        if order and hasattr(order, "rider_rating") and order.rider_rating is not None:
            ratings.append(order.rider_rating)
    if not ratings:
        rider.rating = 5.0
    else:
        rider.rating = round(sum(ratings) / len(ratings), 10)

